import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier, CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'
import { Timeline } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

export const ProductCostOptionItemInputSchema = z.object({
	variantIds: z.array(z.uuid()).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: MonetaryAmountSchema,
})

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

function buildItems(items: ProductCostOptionInput['items']) {
	return items.map(item => ({
		id: crypto.randomUUID(),
		variantIds: item.variantIds,
		quantity: item.quantity,
		quantityModifier: item.quantityModifier,
		unitCost: item.unitCost,
		variantsHash: hashVariantIds(item.variantIds),
	}))
}

interface PaintedOptionValue {
	items: ReturnType<typeof buildItems>
	startDate: Date
	endDate: Date | null
}
interface PaintedOption {
	id: string
	currency: CurrencyCode
	country?: Country
	values: PaintedOptionValue[]
}

/** Group input options by (currency, country); paint each value onto that key's Timeline. */
function groupAndPaint(inputs: ProductCostOptionInput[]): PaintedOption[] {
	const byKey = new Map<string, PaintedOption>()
	for (const opt of inputs) {
		const key = `${opt.currency}|${opt.country ?? ''}`
		const value: PaintedOptionValue = {
			items: buildItems(opt.items),
			startDate: new Date(opt.startDate),
			endDate: opt.endDate ? new Date(opt.endDate) : null,
		}
		const entry = byKey.get(key)
		if (entry) entry.values = [...new Timeline(entry.values).place(value).entries]
		else byKey.set(key, { id: crypto.randomUUID(), currency: opt.currency, country: opt.country, values: [value] })
	}
	return [...byKey.values()]
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency and country — which in turn
 * hold a `values` Timeline of `{ items }` (the per-variant unit costs that
 * change over time).
 *
 * - Invariant: each option's `values` timeline is non-overlapping
 *   (Timeline-enforced); at most one option per (currency, country).
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Group by (currency, country) and paint each value onto the option's Timeline.
		// Then validate each painted option through ProductCostOptionSchema.
		const options = groupAndPaint(data.options)

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — the full options set. */
	update(data: { options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.options !== undefined) {
			const options = groupAndPaint(data.options)
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

